import json, datetime, pathlib
p=pathlib.Path('packet.md'); prompt=pathlib.Path('extraction-prompt.txt')
log=[]
for x in (prompt,p):
    t=datetime.datetime.now(datetime.timezone.utc).isoformat()
    content=x.read_text()
    log.append({'path':str(x.resolve()),'timestamp':t})
    if x==p: lines=content.splitlines()
pathlib.Path('read-log.jsonl').write_text(''.join(json.dumps(v,ensure_ascii=False)+'\n' for v in log))
