facts=[]
for i,(meaning,modality,patterns) in enumerate(specs,1):
    ev=[]
    for num,line in enumerate(lines,1):
        hit=next((pat for pat in patterns if pat in line),None)
        if hit: ev.append({'line_start':num,'line_end':num,'quote':hit})
    facts.append({'id':f'F{i}','meaning':meaning,'modality':modality,'evidence':ev})
result={'packet_id':'P022','facts':facts,'questions':[],'contradictions':[],'additional_human_inputs':[],'limitations':['同時要求の保証と処理順序は資料上未決。','利用停止中および取消済みから先の状態遷移は定義されていない。']}
s=json.dumps(result,ensure_ascii=False,separators=(',',':'))
pathlib.Path('canonical.json').write_text(s+'\n')
pathlib.Path('raw-response.md').write_text(s+'\n')
assert json.loads(s)==result
assert all(e['quote'] in lines[e['line_start']-1] for f in facts for e in f['evidence'])
print('facts',len(facts),'evidence',sum(len(f['evidence']) for f in facts),'bytes',len(s.encode()))
print('empty evidence',[f['id'] for f in facts if not f['evidence']])
